legend.example:
// client
const { WorldMap, Blip } = kcds.world;

WorldMap.setMapCategory('Shop', false);
Blip.create({
  position: new kcds.math.Vector3(1652.5, 2151.5, 37),
  type: 'Shop',
  label: 'Our stall',
  legend: false,
});

